<template>
  <div class="page-container disaster-page">
    <div class="page-head"><div><h2>防灾减灾与灾情管理</h2><p>预警、灾情、救助行动一体化管理，全省预警向下级自动可见。</p></div><el-button type="primary" @click="openCreate">新增灾情</el-button></div>
    <div class="stat-grid"><StatCard label="有效预警" :value="alerts.length" unit="条" icon="Warning" color="#e67e22"/><StatCard label="灾情记录" :value="disasters.length" unit="条" icon="Document"/><StatCard label="处置中" :value="processingCount" unit="条" icon="Operation" color="#e6a23c"/><StatCard label="受灾面积" :value="affectedArea.toLocaleString()" unit="亩" icon="DataLine" color="#9b59b6"/></div>
    <div class="panel alert-panel"><div class="panel-title"><span class="title-text">有效预警</span><span class="title-extra">当前角色：{{ userStore.regionName }}</span></div><div class="alert-list"><div v-for="item in alerts" :key="item.id" class="alert-item"><div class="alert-icon">!</div><div><b>{{ item.type }} · {{ item.level }}预警</b><span>{{ item.region }} · {{ item.publishTime }}</span><p>{{ item.content }}</p><small>重点作物：{{ item.crops }}</small></div></div></div></div>
    <div class="panel table-panel"><div class="panel-title"><span class="title-text">灾情列表</span><el-form :inline="true"><el-form-item label="状态"><el-select v-model="statusFilter" clearable placeholder="全部" style="width:120px"><el-option v-for="item in statusOptions" :key="item" :label="item" :value="item"/></el-select></el-form-item></el-form></div><el-table :data="filteredDisasters" stripe><el-table-column prop="date" label="发生日期" width="110"/><el-table-column prop="region" label="受灾地区" min-width="150"/><el-table-column prop="type" label="灾害类型" width="100"/><el-table-column prop="crop" label="受灾作物" width="100"/><el-table-column prop="affectedArea" label="影响面积(亩)" width="120" align="right"/><el-table-column prop="disasterArea" label="成灾面积(亩)" width="120" align="right"/><el-table-column label="状态" width="95"><template #default="{row}"><el-tag :type="row.status==='已处置'?'success':row.status==='处置中'?'warning':'danger'">{{ row.status }}</el-tag></template></el-table-column><el-table-column label="操作" width="210"><template #default="{row}"><el-button link type="primary" @click="showDetail(row)">详情</el-button><el-button link type="success" @click="openAction(row)">新增救助行动</el-button><el-button link @click="openStatus(row)">更新状态</el-button></template></el-table-column></el-table></div>
    <el-drawer v-model="detailVisible" title="灾情详情与救助行动" size="520px"><template v-if="current"><el-descriptions :column="1" border><el-descriptions-item label="灾情编号">{{ current.id }}</el-descriptions-item><el-descriptions-item label="地区/日期">{{ current.region }} / {{ current.date }}</el-descriptions-item><el-descriptions-item label="灾害/作物">{{ current.type }} / {{ current.crop }}</el-descriptions-item><el-descriptions-item label="面积">影响 {{ current.affectedArea }} 亩，成灾 {{ current.disasterArea }} 亩，绝收 {{ current.lostArea }} 亩</el-descriptions-item><el-descriptions-item label="预估损失">{{ current.estLoss }}</el-descriptions-item><el-descriptions-item label="情况说明">{{ current.description }}</el-descriptions-item></el-descriptions><div class="timeline-head"><h4>救助行动时间线</h4><el-button type="primary" link @click="openAction(current)">新增行动</el-button></div><el-empty v-if="!actions.length" description="暂无救助行动"/><el-timeline v-else><el-timeline-item v-for="item in actions" :key="item.id" :timestamp="item.time" placement="top"><b>{{ item.phase }} · {{ item.unit }}</b><p>{{ item.action }}</p><small>{{ item.result }}</small></el-timeline-item></el-timeline></template></el-drawer>
    <el-dialog v-model="createVisible" title="新增灾情" width="560px"><el-form ref="formRef" :model="form" :rules="rules" label-width="105px"><el-form-item label="灾害类型" prop="type"><el-select v-model="form.type" style="width:100%"><el-option label="暴雨渍涝" value="渍涝"/><el-option label="风雹" value="风雹"/><el-option label="干旱" value="干旱"/><el-option label="低温冻害" value="低温冻害"/></el-select></el-form-item><el-form-item label="发生日期" prop="date"><el-date-picker v-model="form.date" type="date" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item><el-form-item label="受灾地区" prop="region"><el-input v-model="form.region"/></el-form-item><el-form-item label="地区编码" prop="regionCode"><el-input v-model="form.regionCode" placeholder="如 341222"/></el-form-item><el-form-item label="受灾作物" prop="crop"><el-input v-model="form.crop"/></el-form-item><el-form-item label="影响面积(亩)" prop="affectedArea"><el-input-number v-model="form.affectedArea" :min="0" style="width:100%"/></el-form-item><el-form-item label="成灾面积(亩)" prop="disasterArea"><el-input-number v-model="form.disasterArea" :min="0" style="width:100%"/></el-form-item><el-form-item label="绝收面积(亩)" prop="lostArea"><el-input-number v-model="form.lostArea" :min="0" style="width:100%"/></el-form-item><el-form-item label="预估损失" prop="estLoss"><el-input v-model="form.estLoss" placeholder="如：约20万元"/></el-form-item><el-form-item label="情况说明" prop="description"><el-input v-model="form.description" type="textarea" :rows="3"/></el-form-item></el-form><template #footer><el-button @click="createVisible=false">取消</el-button><el-button type="primary" @click="submit">保存</el-button></template></el-dialog>
    <el-dialog v-model="statusVisible" title="更新灾情状态" width="420px"><el-form label-width="85px"><el-form-item label="灾情编号"><span>{{ statusTarget?.id }}</span></el-form-item><el-form-item label="当前状态"><span>{{ statusTarget?.status }}</span></el-form-item><el-form-item label="更新为"><el-select v-model="nextStatus" style="width:100%"><el-option v-for="item in statusOptions" :key="item" :label="item" :value="item"/></el-select></el-form-item></el-form><template #footer><el-button @click="statusVisible=false">取消</el-button><el-button type="primary" @click="submitStatus">确认更新</el-button></template></el-dialog>
    <el-dialog v-model="actionVisible" title="新增救助行动" width="520px"><el-form ref="actionFormRef" :model="actionForm" :rules="actionRules" label-width="90px"><el-form-item label="灾情编号"><span>{{ actionTarget?.id }}</span></el-form-item><el-form-item label="行动阶段" prop="phase"><el-select v-model="actionForm.phase" style="width:100%"><el-option label="灾前应急" value="灾前应急"/><el-option label="灾中处置" value="灾中处置"/><el-option label="灾后救助" value="灾后救助"/></el-select></el-form-item><el-form-item label="执行单位" prop="unit"><el-input v-model="actionForm.unit"/></el-form-item><el-form-item label="救助行动" prop="action"><el-input v-model="actionForm.action" type="textarea" :rows="3"/></el-form-item><el-form-item label="行动时间" prop="time"><el-date-picker v-model="actionForm.time" type="datetime" value-format="YYYY-MM-DD HH:mm" style="width:100%"/></el-form-item><el-form-item label="行动结果" prop="result"><el-input v-model="actionForm.result" type="textarea" :rows="2"/></el-form-item></el-form><template #footer><el-button @click="actionVisible=false">取消</el-button><el-button type="primary" @click="submitAction">保存行动</el-button></template></el-dialog>
  </div>
</template>
<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import StatCard from '@/components/common/StatCard.vue'
import { useUserStore } from '@/stores/user'
import { addDisaster, addRescueAction, fetchDisasters, fetchRescueActions, fetchWeatherAlerts, updateDisasterStatus } from '@/api/gpm'

const userStore=useUserStore(); const alerts=ref([]); const disasters=ref([]); const current=ref(null); const actions=ref([]); const detailVisible=ref(false); const createVisible=ref(false); const statusVisible=ref(false); const actionVisible=ref(false); const statusFilter=ref(''); const formRef=ref(null); const actionFormRef=ref(null); const statusTarget=ref(null); const actionTarget=ref(null); const nextStatus=ref('处置中'); const statusOptions=['待核实','处置中','已处置']; const today=()=>new Date().toISOString().slice(0,10); const now=()=>new Date().toISOString().slice(0,16).replace('T',' ')
const form=reactive({type:'渍涝',date:today(),region:'',regionCode:'',crop:'玉米',affectedArea:0,disasterArea:0,lostArea:0,estLoss:'待评估',description:''}); const actionForm=reactive({phase:'灾中处置',unit:'',action:'',time:now(),result:''})
const validateAreas=(rule,value,callback)=>{if(Number(form.affectedArea)<=0)return callback(new Error('影响面积必须大于0'));if(Number(form.disasterArea)>Number(form.affectedArea))return callback(new Error('成灾面积不能大于影响面积'));if(Number(form.lostArea)>Number(form.disasterArea))return callback(new Error('绝收面积不能大于成灾面积'));callback()}; const rules={type:[{required:true,message:'请选择灾害类型'}],date:[{required:true,message:'请选择发生日期'}],region:[{required:true,message:'请输入地区'}],regionCode:[{required:true,message:'请输入编码'}],crop:[{required:true,message:'请输入受灾作物'}],affectedArea:[{validator:validateAreas,trigger:'change'}],disasterArea:[{validator:validateAreas,trigger:'change'}],lostArea:[{validator:validateAreas,trigger:'change'}],estLoss:[{required:true,message:'请输入预估损失'}],description:[{required:true,message:'请输入情况说明'}]}; const actionRules={phase:[{required:true,message:'请选择行动阶段'}],unit:[{required:true,message:'请输入执行单位'}],action:[{required:true,message:'请输入救助行动'}],time:[{required:true,message:'请选择行动时间'}],result:[{required:true,message:'请输入行动结果'}]}
const filteredDisasters=computed(()=>disasters.value.filter(item=>!statusFilter.value||item.status===statusFilter.value)); const processingCount=computed(()=>disasters.value.filter(item=>item.status!=='已处置').length); const affectedArea=computed(()=>disasters.value.reduce((sum,item)=>sum+Number(item.affectedArea||0),0)); const load=async()=>{alerts.value=await fetchWeatherAlerts(userStore.role);disasters.value=await fetchDisasters(userStore.role)}; const showDetail=async row=>{current.value=row;actions.value=await fetchRescueActions(row.id);detailVisible.value=true}
const openCreate=()=>{Object.assign(form,{type:'渍涝',date:today(),region:userStore.regionName||'',regionCode:userStore.role?.regionCode||'',crop:'玉米',affectedArea:0,disasterArea:0,lostArea:0,estLoss:'待评估',description:''});createVisible.value=true}; const submit=async()=>{await formRef.value.validate();const result=await addDisaster({...form});if(!result.success)return ElMessage.error(result.message);ElMessage.success('灾情已新增');createVisible.value=false;await load()}
const openStatus=row=>{statusTarget.value=row;nextStatus.value=row.status;statusVisible.value=true}; const submitStatus=async()=>{const result=await updateDisasterStatus(statusTarget.value.id,nextStatus.value);if(!result.success)return ElMessage.error(result.message);ElMessage.success('灾情状态已更新');statusVisible.value=false;await load();if(current.value?.id===statusTarget.value.id)current.value={...current.value,status:nextStatus.value}}
const openAction=row=>{actionTarget.value=row;Object.assign(actionForm,{phase:'灾中处置',unit:userStore.role?.unit||userStore.regionName||'属地农业农村部门',action:'',time:now(),result:''});actionVisible.value=true}; const submitAction=async()=>{await actionFormRef.value.validate();const result=await addRescueAction(actionTarget.value.id,{...actionForm});if(!result.success)return ElMessage.error(result.message);ElMessage.success('救助行动已新增');actionVisible.value=false;if(current.value?.id===actionTarget.value.id)actions.value=await fetchRescueActions(actionTarget.value.id)}
onMounted(load)
</script>
<style lang="scss" scoped>.disaster-page{gap:12px;overflow:auto}.page-head{display:flex;justify-content:space-between;align-items:flex-start}.page-head h2{font-size:22px;margin-bottom:6px}.page-head p{color:var(--ah-text-secondary)}.stat-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.alert-list{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.alert-item{display:flex;gap:10px;padding:14px;background:#fff8ee;border:1px solid #f7d5a5;border-radius:8px}.alert-icon{flex:none;width:24px;height:24px;border-radius:50%;background:#e67e22;color:#fff;text-align:center;line-height:24px;font-weight:700}.alert-item span,.alert-item p,.alert-item small{display:block;color:var(--ah-text-secondary);font-size:12px;margin-top:5px;line-height:1.6}.alert-item b{font-size:14px}.table-panel{min-height:420px}.table-panel :deep(.el-form-item){margin-bottom:0}.timeline-head{display:flex;align-items:center;justify-content:space-between;margin:24px 0 14px}.timeline-head h4{margin:0}@media(max-width:1050px){.stat-grid{grid-template-columns:repeat(2,1fr)}.alert-list{grid-template-columns:1fr}.page-head{display:block}.page-head .el-button{margin-top:12px}}</style>
